package com.jobpilot.auth;import com.jobpilot.user.*;import org.springframework.security.authentication.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import static org.springframework.http.HttpStatus.CONFLICT;
@Service public class AuthService{private final UserRepository users;private final PasswordEncoder encoder;private final AuthenticationManager manager;private final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,AuthenticationManager m,JwtService j){users=u;encoder=e;manager=m;jwt=j;}public AuthDtos.AuthResponse register(AuthDtos.RegisterRequest r){if(users.findByEmail(r.email()).isPresent())throw new ResponseStatusException(CONFLICT,"Email already registered");var u=new User();u.setName(r.name());u.setEmail(r.email().toLowerCase());u.setPassword(encoder.encode(r.password()));users.save(u);return response(u);}public AuthDtos.AuthResponse login(AuthDtos.LoginRequest r){manager.authenticate(new UsernamePasswordAuthenticationToken(r.email(),r.password()));return response(users.findByEmail(r.email()).orElseThrow());}private AuthDtos.AuthResponse response(User u){return new AuthDtos.AuthResponse(jwt.generate(u.getEmail()),new AuthDtos.UserView(u.getId(),u.getName(),u.getEmail()));}}
